// Generated from student sources. Local Blob downloads work offline.
(()=>{const data={"lesson08-student.zip": "", "lecture_note_08.md": "", "lesson08.py": "", "lesson08.R": "", "equipment.csv": ""};const urls=new Map(Object.entries(data).map(([n,b])=>[n,URL.createObjectURL(new Blob([Uint8Array.from(atob(b),c=>c.charCodeAt(0))]))]));
function prepare(a){const u=urls.get(a?.getAttribute('download'));if(u)a.href=u;}
document.querySelectorAll('a[download]').forEach(prepare);document.addEventListener('click',e=>prepare(e.target.closest?.('a[download]')));})();
